local HeraldicFlagMaker = {}
local PRODUCTS = {
    pennant = { name = "Kljunasta zastavica", linenCost = 1, paintCost = 1, time = 1, cost = 12, moraleBoost = 2, prestige = 1, description = "Preprosta kljunasta zastavica za viteze." },
    gonfalon = { name = "Gonfalon", linenCost = 2, paintCost = 1, time = 3, cost = 45, moraleBoost = 5, prestige = 3, description = "Visok strm gonfalon za čete." },
    heraldic_standard = { name = "Heraldični standard", silkCost = 2, paintCost = 1, threadCost = 1, time = 5, cost = 130, moraleBoost = 9, prestige = 7, happiness = 1, description = "Standard z družinskim grbom." },
    royal_house_flag = { name = "Kraljevska hišna zastava", silkCost = 2, goldCost = 1, threadCost = 1, paintCost = 1, time = 7, cost = 320, moraleBoost = 14, prestige = 14, happiness = 2, description = "Zastava kraljevske hiše z zlatimi nitmi." },
    battle_standard = { name = "Bojni standard", silkCost = 3, silverCost = 1, threadCost = 1, paintCost = 1, time = 9, cost = 700, moraleBoost = 20, prestige = 22, happiness = 4, description = "Bojni standard za najvišje morale čet." },
    royal_ceremonial_standard = { name = "Kraljevski slovesni standard", silkCost = 4, goldCost = 2, silverCost = 1, jewelCost = 1, threadCost = 2, paintCost = 2, time = 13, cost = 1800, moraleBoost = 35, prestige = 50, happiness = 10, description = "Kraljevski slovesni standard z dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Zastavarska delavnica", cost = { gold = 250, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    heraldry_room = { name = "Heraldična soba", cost = { gold = 800, wood = 220, stone = 200, paint = 6 }, upkeep = 20, qualityBonus = 18 },
    gilding_room = { name = "Pozlatnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, gold = 6 }, upkeep = 40, qualityBonus = 30 },
    royal_flag_atelier = { name = "Kraljevski atelje zastav", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silk = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
HeraldicFlagMaker.linenStock = 14; HeraldicFlagMaker.silkStock = 10; HeraldicFlagMaker.paintStock = 10; HeraldicFlagMaker.threadStock = 8; HeraldicFlagMaker.goldStock = 6; HeraldicFlagMaker.silverStock = 6; HeraldicFlagMaker.jewelStock = 4
HeraldicFlagMaker.productStock = {}; HeraldicFlagMaker.buildings = {}; HeraldicFlagMaker.maker = nil; HeraldicFlagMaker.activeMaking = {}; HeraldicFlagMaker.totalProducts = 0; HeraldicFlagMaker.dayTimer = 0
function HeraldicFlagMaker.init() HeraldicFlagMaker.linenStock=14; HeraldicFlagMaker.silkStock=10; HeraldicFlagMaker.paintStock=10; HeraldicFlagMaker.threadStock=8; HeraldicFlagMaker.goldStock=6; HeraldicFlagMaker.silverStock=6; HeraldicFlagMaker.jewelStock=4; HeraldicFlagMaker.productStock={}; HeraldicFlagMaker.buildings={}; HeraldicFlagMaker.maker=nil; HeraldicFlagMaker.activeMaking={}; HeraldicFlagMaker.totalProducts=0; HeraldicFlagMaker.dayTimer=0; print("[HeraldicFlagMaker] Royal Heraldic Flag Maker System initialized (6 products, 4 buildings)") end
function HeraldicFlagMaker.hireMaker(n,s) s=s or math.random(50,90); local c=450+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HeraldicFlagMaker.maker={name=n or ("Zastavar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zastavar najet: %s (spretnost: %d)",HeraldicFlagMaker.maker.name,s),"success") end; return true end
function HeraldicFlagMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HeraldicFlagMaker.build(id) local ok,e=HeraldicFlagMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HeraldicFlagMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HeraldicFlagMaker.getQualityBonus() local b=0; for _,bd in ipairs(HeraldicFlagMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HeraldicFlagMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.linenCost and HeraldicFlagMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lana" end; if d.silkCost and HeraldicFlagMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.paintCost and HeraldicFlagMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.threadCost and HeraldicFlagMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.goldCost and HeraldicFlagMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and HeraldicFlagMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and HeraldicFlagMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HeraldicFlagMaker.buildings==0 then return false,"Potrebna delavnica" end; if not HeraldicFlagMaker.maker then return false,"Potreben zastavar" end; return true end
function HeraldicFlagMaker.make(pt,qty) qty=qty or 1; local ok,e=HeraldicFlagMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.linenCost then HeraldicFlagMaker.linenStock=HeraldicFlagMaker.linenStock-d.linenCost*qty end; if d.silkCost then HeraldicFlagMaker.silkStock=HeraldicFlagMaker.silkStock-d.silkCost*qty end; if d.paintCost then HeraldicFlagMaker.paintStock=HeraldicFlagMaker.paintStock-d.paintCost*qty end; if d.threadCost then HeraldicFlagMaker.threadStock=HeraldicFlagMaker.threadStock-d.threadCost*qty end; if d.goldCost then HeraldicFlagMaker.goldStock=HeraldicFlagMaker.goldStock-d.goldCost*qty end; if d.silverCost then HeraldicFlagMaker.silverStock=HeraldicFlagMaker.silverStock-d.silverCost*qty end; if d.jewelCost then HeraldicFlagMaker.jewelStock=HeraldicFlagMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if HeraldicFlagMaker.maker then t=math.max(1,t-math.floor(HeraldicFlagMaker.maker.skill/12)) end; table.insert(HeraldicFlagMaker.activeMaking,{id="flag_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,moraleBoost=d.moraleBoost or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HeraldicFlagMaker.completeMaking(m) local q=1.0+(HeraldicFlagMaker.getQualityBonus()/100); if HeraldicFlagMaker.maker then q=q+(HeraldicFlagMaker.maker.skill/180) end; q=math.min(2.0,q); HeraldicFlagMaker.productStock[m.productType]=(HeraldicFlagMaker.productStock[m.productType] or 0)+m.quantity; HeraldicFlagMaker.totalProducts=HeraldicFlagMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HeraldicFlagMaker.maker then HeraldicFlagMaker.maker.itemsMade=HeraldicFlagMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then HeraldicFlagMaker.maker.skill=math.min(100,HeraldicFlagMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zastava izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"heraldicflag.completed",{productName=m.productName,prestige=m.prestige,moraleBoost=m.moraleBoost}) end end
function HeraldicFlagMaker.update(dt) if not _G.state then return end; HeraldicFlagMaker.dayTimer=HeraldicFlagMaker.dayTimer+dt; if HeraldicFlagMaker.dayTimer>=30 then HeraldicFlagMaker.dayTimer=0; for i=#HeraldicFlagMaker.activeMaking,1,-1 do local m=HeraldicFlagMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HeraldicFlagMaker.completeMaking(m); table.remove(HeraldicFlagMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HeraldicFlagMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HeraldicFlagMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HeraldicFlagMaker.getStats() return {linenStock=HeraldicFlagMaker.linenStock,silkStock=HeraldicFlagMaker.silkStock,paintStock=HeraldicFlagMaker.paintStock,threadStock=HeraldicFlagMaker.threadStock,goldStock=HeraldicFlagMaker.goldStock,silverStock=HeraldicFlagMaker.silverStock,jewelStock=HeraldicFlagMaker.jewelStock,productStock=HeraldicFlagMaker.productStock,numBuildings=#HeraldicFlagMaker.buildings,hasMaker=HeraldicFlagMaker.maker~=nil,makerName=HeraldicFlagMaker.maker and HeraldicFlagMaker.maker.name or "—",makerSkill=HeraldicFlagMaker.maker and HeraldicFlagMaker.maker.skill or 0,activeMaking=#HeraldicFlagMaker.activeMaking,totalProducts=HeraldicFlagMaker.totalProducts} end
return HeraldicFlagMaker
